namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes over the dough.", "Tear mozzarella and distribute evenly.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                TotalRatings = 12, RatingSum = 52
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy pasta with pancetta and Parmesan.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper", "Salt"],
                Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crispy.", "Whisk eggs with grated Parmesan and pepper.", "Drain pasta, reserving some water.", "Toss hot pasta with pancetta, then quickly stir in egg mixture.", "Serve immediately with extra Parmesan."],
                TotalRatings = 8, RatingSum = 38
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or pan-fry the chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and simmer.", "Stir in cream and garam masala.", "Add chicken and simmer for 10 minutes."],
                TotalRatings = 15, RatingSum = 70
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
                Description = "Stir-fried rice noodles with vegetables and a tangy sauce.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Peanuts", "Lime", "Fish sauce", "Tamarind paste", "Eggs"],
                Steps = ["Soak rice noodles in warm water for 20 minutes.", "Mix tamarind paste, fish sauce, and sugar for the sauce.", "Fry tofu until golden.", "Scramble eggs in the wok.", "Add noodles and sauce, toss to coat.", "Garnish with peanuts, bean sprouts, and lime."],
                TotalRatings = 6, RatingSum = 26
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in crispy taco shells with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer until thickened.", "Warm taco shells in the oven.", "Fill shells with beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa."],
                TotalRatings = 10, RatingSum = 42
            },
            new Recipe
            {
                Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Rich chocolate cake with a gooey molten center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = ["Preheat oven to 425°F.", "Melt chocolate and butter together.", "Whisk in eggs, sugar, and vanilla.", "Fold in flour gently.", "Pour into greased ramekins.", "Bake for 12-14 minutes until edges are set but center is soft."],
                TotalRatings = 20, RatingSum = 95
            },
            new Recipe
            {
                Id = 7, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and creamy avocado dip.",
                Ingredients = ["Avocados", "Lime juice", "Red onion", "Cilantro", "Jalapeño", "Salt", "Tomato"],
                Steps = ["Halve and pit avocados, scoop into a bowl.", "Mash to desired consistency.", "Mix in lime juice, diced onion, cilantro, and jalapeño.", "Fold in diced tomato.", "Season with salt and serve with chips."],
                TotalRatings = 9, RatingSum = 40
            },
            new Recipe
            {
                Id = 8, Title = "Green Curry", Category = "Thai",
                Description = "Aromatic coconut curry with vegetables and Thai basil.",
                Ingredients = ["Green curry paste", "Coconut milk", "Chicken or tofu", "Bamboo shoots", "Thai basil", "Fish sauce", "Sugar", "Rice"],
                Steps = ["Heat coconut cream in a pot until oil separates.", "Fry curry paste for 2 minutes.", "Add protein and cook through.", "Pour in remaining coconut milk.", "Add bamboo shoots, fish sauce, and sugar.", "Simmer 10 minutes, finish with Thai basil. Serve over rice."],
                TotalRatings = 7, RatingSum = 31
            },
        ];
        _nextId = 9;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title.Trim(),
            Category = submission.Category.Trim(),
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
        };
        _recipes.Add(recipe);
    }
}

